import java.util.Scanner;
import java.util.Stack;

public class AK375 {
    public static Scanner cin = new Scanner(System.in);

    public String ak375(int n, String str) {
        Stack<Integer> stack = new Stack<>();
        int res1 = 0;
        int res2 = 0;
        int currentLen = 0;

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                stack.push(currentLen);
                currentLen = 0;
                res2++;
            } else if (c == ')') {
                if (!stack.isEmpty()) {
                    currentLen = stack.pop();
                }
                if (currentLen > res1) {
                    res1 = currentLen;
                }
                currentLen = 0;
            } else {
                currentLen++;
            }
        }
        if (currentLen > res1) {
            res1 = currentLen;
        }

        return res1 + " " + res2;
    }

    public static void main(String[] args) {
        while (cin.hasNext()) {
            int n = cin.nextInt();
            String str = cin.next();
            String res = new AK375().ak375(n, str);
            System.out.println(res);
        }
    }
}
